nextflow_process {

    name "Test Process ANNDATA_GETSIZE"
    script "../main.nf"
    process "ANNDATA_GETSIZE"

    tag "modules"
    tag "modules_nfcore"
    tag "anndata"
    tag "anndata/getsize"

    test("scdownstream - h5ad - cells") {

        when {
            process {
                """
                input[0] = [
                    [ id:'test' ],
                    file(params.modules_testdata_base_path + 'genomics/homo_sapiens/scrnaseq/h5ad/pbmc1k.h5ad', checkIfExists: true),
                ]
                input[1] = 'cells'
                """
            }
        }

        then {
            assertAll(
                { assert process.success },
                { assert snapshot(
                    sanitizeOutput(process.out),
                    path(process.out.versions_anndata[0]).yaml
                ).match() }
            )
        }

    }

    test("scdownstream - h5ad - genes") {

